#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    bool makeEqual(vector<string>& words) {
        int n = words.size();
        int count[26] = {0};
        for (const string& w : words) {
            for (char c : w) {
                count[c - 'a']++;
            }
        }
        for (int i = 0; i < 26; ++i) {
            if (count[i] % n != 0) return false;
        }
        return true;
    }
};

class Solution {
    public boolean makeEqual(String[] words) {
        int n = words.length;
        int[] count = new int[26];
        for (String w : words) {
            for (int i = 0; i < w.length(); ++i) {
                count[w.charAt(i) - 'a']++;
            }
        }
        for (int c : count) {
            if (c % n != 0) return false;
        }
        return true;
    }
}

/**
 * @param {string[]} words
 * @return {boolean}
