var makeEqual = function(words) {
    const n = words.length;
    const count = new Array(26).fill(0);
    for (const w of words) {
        for (let i = 0; i < w.length; ++i) {
            count[w.charCodeAt(i) - 97]++;
        }
    }
    for (let i = 0; i < 26; ++i) {
        if (count[i] % n !== 0) return false;
    }
    return true;
};
